/* ---------- Hero / cover decor ---------- */

.cover {
  position: relative;
  overflow: hidden;
  background: var(--c-pink);
  color: var(--c-white);
  isolation: isolate;
}

.cover--blue { background: var(--c-blue); }
.cover--night { background: var(--c-night); }

/* Two floating blobs: a sun-yellow circle and a soft ring */
.cover::before, .cover::after {
  content: "";
  position: absolute;
  z-index: -1;
  pointer-events: none;
  border-radius: 50%;
}

.cover::before {
  width: 70vmax;
  height: 70vmax;
  right: -28vmax;
  top: -30vmax;
  background: var(--c-sun);
  opacity: 0.9;
